            # Process remaining components first, then prepend target
            remaining = components[i+1:]

            # Parse the target
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative to the directory containing the link
                if candidate == '/':
                    current = '/'
